const SECURITY_KEY='InsectMES_Rev031_security_v1';
let securityData,openTopMenu='',restoringRoute=false,routePause=false,lastRouteKey='',formDraft=null,cpCode='EGG';
const levelNames=['Sin acceso','Consulta','Edición','Edición + eliminar','Administrador'];
function securitySeed(){const defaults=[['admin','Administrador',4,true],['read','Consulta',1,false],['edit','Edición',2,false],['delete','Edición + eliminar',3,false]];return {users:[],profiles:defaults.map(([id,name,n,admin])=>({id,name,admin,permissions:Object.fromEntries(screenRegistry.map(x=>[x.id,['users','profiles','hierarchy'].includes(x.id)&&!admin?0:n]))}))};}
function initSecurity(){if(securityData)return;try{securityData=JSON.parse(localStorage.getItem(SECURITY_KEY) || localStorage.getItem('InsectMES_Rev029_security_v1') || localStorage.getItem('InsectMES_security_v1'));}catch{}securityData??=securitySeed();for(const p of securityData.profiles)for(const x of screenRegistry)p.permissions[x.id]??=p.admin?4:0;persistSecurity();}
function persistSecurity(){localStorage.setItem(SECURITY_KEY,JSON.stringify(securityData));}
function currentProfile(){initSecurity();const user=securityData.users.find(x=>x.id===shellSession?.accountId);return securityData.profiles.find(x=>x.id===(user?.profile||shellSession?.profile||'admin'));}
function levelFor(screen=shellScreen){const p=currentProfile();return p?.admin?4:p?.permissions[screen]??0;}
function requireLevel(level,screen=shellScreen){if(!shellSession||levelFor(screen)<level){showMsg('No tienes permiso para realizar esta acción',true);return false;}return true;}
async function passwordRecord(password,salt){const bytes=salt?Uint8Array.from(salt):crypto.getRandomValues(new Uint8Array(16));const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const result=await crypto.subtle.deriveBits({name:'PBKDF2',salt:bytes,iterations:150000,hash:'SHA-256'},key,256);return {salt:Array.from(bytes),hash:Array.from(new Uint8Array(result)).map(x=>x.toString(16).padStart(2,'0')).join('')};}
screenRegistry.push({id:'units',module:'Datos maestros',name:'Unidades',section:'units'},{id:'users',module:'Seguridad',name:'Usuarios',concept:'users'},{id:'profiles',module:'Seguridad',name:'Perfiles de seguridad',concept:'profiles'});
const baseInitShell29=initShell;
initShell=function(){baseInitShell29();initSecurity();state.operationRuns??=[];state.productionLots??=[];state.cpOperations??=bsfFlow.map(x=>({code:x[0],name:x[1],wc:'WC-'+x[0],workcenter:x[5],part:({EGG:'BSF002',NUR:'BSF004',TRA:'WIP-LAR',REA:'WIP-LAR',HAR:'BSF005',WAS:'BSF005',SAN:'BSF005',DRY:'SB001',FRA:'SB-FLA',GRI:'FG-MEAL',PAC:'FG001',BOX:'FG-BOX',SHP:'FG-BOX',PUP:'BSF006',DAR:'BSF001',LOV:'EGG-RAW'})[x[0]],input:({NUR:'BSF002',TRA:'BSF004',REA:'WIP-LAR',HAR:'WIP-LAR',WAS:'BSF005',SAN:'BSF005',DRY:'BSF005',FRA:'SB001',GRI:'SB-FLA',PAC:'SB001',BOX:'FG001',SHP:'FG-BOX',PUP:'BSF005',DAR:'BSF006',LOV:'BSF001'})[x[0]]||'',inputName:({EGG:'Jaula de reproducción',NUR:'Huevos',TRA:'5-DOL',REA:'Larvero',HAR:'Larvero 17-DOL',WAS:'17-DOL',SAN:'Larva enjuagada',DRY:'Larva sanitizada',FRA:'Pop Larvae',GRI:'Flake Larvae',PAC:'Larva deshidratada',BOX:'Producto empacado',SHP:'Caja',PUP:'17-DOL',DAR:'Pupas',LOV:'Moscas'})[x[0]],output:x[4],unit:x[0]==='EGG'?'g':['DAR','LOV','PAC','BOX','SHP'].includes(x[0])?'pc':'kg',units:[x[0]==='EGG'?'g':['DAR','LOV','PAC','BOX','SHP'].includes(x[0])?'pc':'kg'],duration:x[6]}));for(const o of state.cpOperations){if(!state.parts.some(p=>p.part===o.part))state.parts.push({part:o.part,desc:o.output,unit:o.unit,itemType:['PAC','BOX','SHP'].includes(o.code)?'Producto Terminado':'WIP',serialPrefix:'BSF'});if(!state.setupTables.Locations.some(l=>l.code===o.wc))state.setupTables.Locations.push({code:o.wc,description:o.workcenter,active:true,locationType:'Workcenter'});}if(!state.setupTables.Serial_Prefix.some(p=>p.code==='BSF'))state.setupTables.Serial_Prefix.push({code:'BSF',active:true,lastNumber:0,description:'Producción BSF'});};
loginScreen=function(){initSecurity();document.getElementById('demoLogin')?.remove();const first=!securityData.users.length;const el=document.createElement('section');el.id='demoLogin';el.innerHTML=`<div class="login-card"><div class="login-wordmark">Insect<span>MES</span></div><h1>${first?'Crear acceso':'Iniciar sesión'}</h1><form onsubmit="event.preventDefault();enterDemo()"><label>Compañía<input class="input" id="loginCompany" value="Insetti" required autocomplete="organization"></label>${first?'<label>Nombre<input class="input" id="loginName" value="Alejandro" required autocomplete="name"></label>':''}<label>Correo electrónico<input class="input" type="email" id="loginEmail" required autocomplete="username"></label><label>Contraseña<input class="input" id="loginPassword" type="password" minlength="8" required autocomplete="${first?'new-password':'current-password'}"></label><div id="loginError" role="alert"></div><button class="btn primary" id="loginSubmit">${first?'Crear cuenta e ingresar':'Iniciar sesión'}</button></form></div>`;document.body.append(el);};
enterDemo=async function(){initSecurity();const email=document.getElementById('loginEmail').value.trim().toLowerCase(),password=document.getElementById('loginPassword').value,company=document.getElementById('loginCompany').value.trim();const button=document.getElementById('loginSubmit');button.disabled=true;try{let user;if(!securityData.users.length){if(password.length<8)throw Error('La contraseña debe tener al menos 8 caracteres.');user={id:'U-'+Date.now(),name:document.getElementById('loginName').value.trim(),email,company,profile:'admin',active:true,...await passwordRecord(password)};securityData.users.push(user);persistSecurity();}else{user=securityData.users.find(x=>x.email===email&&x.company.toLowerCase()===company.toLowerCase()&&x.active);if(!user||(await passwordRecord(password,user.salt)).hash!==user.hash)throw Error('Correo o contraseña incorrectos.');}shellSession={company:user.company,user:user.name,accountId:user.id,profile:user.profile};sessionStorage.setItem(SESSION_KEY,JSON.stringify(shellSession));document.getElementById('demoLogin').remove();navigateScreen('home');}catch(e){document.getElementById('loginError').textContent=e.message;}finally{button.disabled=false;}};
logoutDemo=function(){sessionStorage.removeItem(SESSION_KEY);shellSession=null;closeIfOpen();closeTopMenus();loginScreen();};
const icons29={menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',gear:'<path d="m9 3-1 3-3 1-2 3 2 2-1 3 3 2 1 3h4l1-3 3-1 2-3-2-2 1-3-3-2-1-3Z"/><circle cx="10.5" cy="11.5" r="3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3v.1"/>',box:'<path d="m3 7 9-4 9 4-9 4ZM3 7v10l9 4 9-4V7M12 11v10"/>',arrow:'<path d="M3 12h18m-7-7 7 7-7 7"/>',fly:'<path d="M12 8v12m-3-5h6M9 5l3 3 3-3M9 12C0 2 1 17 9 15m6-3c9-10 8 5 0 3"/>'};
const icon29=name=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons29[name]||icons29.box}</svg>`;
contextBar=function(){return '';};configInfo=function(){return '';};
renderShell=function(){document.querySelector('.brand-title').textContent='InsectMES';document.querySelector('.topbar').innerHTML=`<div class="shell-identity"><button class="toolbar-icon" aria-label="Abrir menú de módulos" onclick="showSidebar()">${icon29('menu')}</button><button class="wordmark" onclick="navigateScreen('home')">Insect<span>MES</span></button><div class="identity-line"><span>${esc(shellSession?.user||'Alejandro')}</span><span>${esc(shellSession?.company||'Insetti')}</span><b id="pageTitle">${esc(screenName())}</b></div></div><div class="shell-tools"><div class="menu-anchor"><button class="toolbar-icon" aria-label="Pantallas recientes" aria-expanded="false" onclick="toggleTopMenu('recent',this)">${icon29('clock')}</button></div><div class="menu-anchor"><button class="toolbar-icon" aria-label="Favoritos" aria-expanded="false" onclick="toggleTopMenu('favorites',this)">${icon29('star')}</button></div><div class="menu-anchor"><button class="toolbar-icon" aria-label="Configuración de pantalla" aria-expanded="false" onclick="toggleTopMenu('config',this)">${icon29('gear')}</button></div><div class="menu-anchor"><button class="toolbar-icon" aria-label="Ayuda" aria-expanded="false" onclick="toggleTopMenu('help',this)">${icon29('help')}</button></div><div class="goto-wrap"><input class="input" id="goToInput" placeholder="Go to…" aria-label="Go to buscar pantalla" oninput="searchScreens(this.value)" onkeydown="if(event.key==='Enter'){event.preventDefault();showSearchResults(this.value)}"><div id="goToResults"></div></div><button class="session-exit" onclick="logoutDemo()">Cerrar sesión</button></div>`;document.getElementById('nav').innerHTML=Object.entries(Object.groupBy(screenRegistry.filter(x=>levelFor(x.id)>0),x=>x.module)).map(([m,list])=>`<details><summary>${esc(m)}</summary>${list.map(x=>`<button class="nav-btn ${x.id===shellScreen?'active':''}" onclick="navigateScreen('${x.id}')">${esc(x.name.replace(/ \/ .*/,''))}</button>`).join('')}</details>`).join('');document.getElementById('sidebarShowBtn').style.display='none';if(currentView==='dashboard')renderHome();if(currentView==='workcenters')renderControlPanel29();};
function closeTopMenus(){document.querySelectorAll('.top-dropdown,.field-dropdown').forEach(x=>x.remove());document.querySelectorAll('.toolbar-icon[aria-expanded]:not(.assistant-launch30)').forEach(x=>x.setAttribute('aria-expanded','false'));openTopMenu='';}
function toggleTopMenu(type,button){const same=openTopMenu===type;closeTopMenus();if(same)return;openTopMenu=type;button.setAttribute('aria-expanded','true');let body='';const link=(label,action)=>`<button role="menuitem" onclick="closeTopMenus();${action}">${label}</button>`;if(type==='recent'||type==='favorites'){const ids=type==='recent'?state.recents:state.favorites;body=`<div class="menu-title">${type==='recent'?'Últimas pantallas':'Favoritos'}</div>`+ids.map(id=>screenRegistry.find(x=>x.id===id)).filter(x=>x&&levelFor(x.id)>0).map(x=>link(esc(x.name),`navigateScreen('${x.id}')`)).join('');if(type==='favorites')body+=link(state.favorites.includes(shellScreen)?'Quitar de favoritos':'Agregar pantalla actual',`toggleFavorite29()`);}if(type==='config'){const names=({'parts':['Item_Type','Serial_Prefix'],'locations':['Location_Type'],'control':['Operation_Type','Workcenter_Status','Container_Status'],'inventory':['Container_Status','Container_Type'],'containers':['Container_Status','Container_Type'],'receive':['Item_Type','Serial_Prefix']})[shellScreen]||[];if(currentView==='workcenters'&&!names.includes('Container_Status'))names.push('Container_Status');body='<div class="menu-title">Configuración</div>'+names.map(n=>link(esc(state.setupSchemas[n].title),`openContextSetup('${n}')`)).join('')+link('Setup Tables',"navigateScreen('setup')")+link('Settings',"openConfigSettings()")+link('Seguridad de esta pantalla',"editScreenSecurity()");}if(type==='help')body='<div class="menu-title">Ayuda</div>'+link('Documentación',"navigateScreen('help')")+link('Significado de los iconos',"navigateScreen('help')");const d=document.createElement('div');d.className='top-dropdown';d.setAttribute('role','menu');d.innerHTML=body||'<div class="menu-title">Sin pantallas recientes</div>';button.parentElement.append(d);}
function toggleFavorite29(){state.favorites=state.favorites.includes(shellScreen)?state.favorites.filter(x=>x!==shellScreen):[...state.favorites,shellScreen];saveState();renderApp();}
document.addEventListener('click',e=>{if(!e.target.closest('.menu-anchor,.field-label,.field-dropdown'))closeTopMenus();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeTopMenus();hideSidebar();}});
const priorNavigate29=navigateScreen;
navigateScreen=function(id){if(shellSession&&levelFor(id)===0){showMsg('No tienes acceso a esta pantalla',true);return;}formDraft=null;closeTopMenus();priorNavigate29(id);};
const homeLogo29=()=>{const m=document.querySelector('.home-brand img');return m?.src||document.querySelector('img[alt="Insetti"]')?.src||logo29;};
let logo29='';
const priorHome29=renderHome;
renderHome=function(){priorHome29();logo29=homeLogo29();document.getElementById('view-dashboard').innerHTML=`<div class="home-heading"><div><div class="section-kicker">INSETTI · OPERACIONES</div><h1>Home</h1><p>Hola, ${esc(shellSession?.user||'Alejandro')}</p></div><img src="${logo29}" alt="Insetti"></div><div class="home-shortcuts">${[['reproduction','Reproducción','fly'],['rearing','Cría','box'],['control','Control Panel','gear'],['inventory','Inventario','box']].filter(x=>levelFor(x[0])>0).map(([id,name,icon])=>`<button onclick="navigateScreen('${id}')">${icon29(icon)}<span>${name}</span><span class="shortcut-arrow">↗</span></button>`).join('')}</div><div class="grid home-grid"><div class="card"><div class="card-head"><div class="card-title">Pendientes</div><span class="count">${state.todos.filter(x=>!x.done&&!/UASLP|setup table/i.test(x.text)).length}</span></div><div class="card-body">${state.todos.filter(x=>!/UASLP|setup table/i.test(x.text)).map((x)=>{const i=state.todos.indexOf(x);return `<label class="concept-check"><input type="checkbox" ${x.done?'checked':''} onchange="state.todos[${i}].done=this.checked;saveState()">${esc(x.text)}</label>`;}).join('')||'<div class="empty-state">No tienes pendientes.</div>'}<form onsubmit="event.preventDefault();addTodo29()"><input class="input" id="newTodo" placeholder="Agregar pendiente" aria-label="Nuevo pendiente"><button class="btn link">Agregar</button></form></div></div><div class="card"><div class="card-head"><div class="card-title">Favoritos</div><button class="btn link" onclick="toggleFavorite29()">${state.favorites.includes('home')?'Quitar Home':'Agregar Home'}</button></div><div class="card-body nav-list">${state.favorites.map(id=>screenRegistry.find(x=>x.id===id)).filter(x=>x&&levelFor(x.id)>0).map(x=>`<button onclick="navigateScreen('${x.id}')">${esc(x.name)}<span>→</span></button>`).join('')}</div></div><div class="card"><div class="card-head"><div class="card-title">Mensajes</div></div><div class="card-body"><div class="empty-state">No hay mensajes nuevos.</div></div></div><div class="card"><div class="card-head"><div class="card-title">Actividad reciente</div></div><div class="card-body nav-list">${state.recents.slice(0,5).map(id=>screenRegistry.find(x=>x.id===id)).filter(x=>x&&levelFor(x.id)>0).map(x=>`<button onclick="navigateScreen('${x.id}')">${esc(x.name)}<span>→</span></button>`).join('')||'<div class="empty-state">Sin actividad reciente.</div>'}</div></div></div>`;};
function addTodo29(){if(!requireLevel(2))return;const text=document.getElementById('newTodo').value.trim();if(text){state.todos.push({text,done:false});saveState();renderApp();}}
function dateLot29(date=new Date()){const pieces=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const f=Object.fromEntries(pieces.map(x=>[x.type,x.value]));return {id:f.year+'-'+f.month+'-'+f.day,label:f.day+' '+['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'][Number(f.month)-1]};}
function op29(){return state.cpOperations.find(x=>x.code===cpCode)||state.cpOperations[0];}
function sourceSerials29(){const o=op29();return state.serials.filter(x=>x.active&&x.qtyCurrent>0&&x.part===o.input&&!x.receiptPending30&&x.status==='OK');}
function scene29(o){return `<svg viewBox="0 0 260 160" aria-hidden="true" class="station-art"><rect x="48" y="58" width="164" height="80" rx="14" fill="#dceadd" stroke="#146344" stroke-width="3"/><path d="M48 84h164M73 138v14m114-14v14" stroke="#146344" stroke-width="4"/><path d="M71 67h118" stroke="#80b9a0" stroke-width="3"/>${Array.from({length:12},(_,i)=>`<ellipse class="bio-dot" cx="${75+i%6*22}" cy="${101+Math.floor(i/6)*20}" rx="${o.code==='EGG'?4:8}" ry="4" fill="${o.code==='EGG'?'#f5db9e':'#a2b4a4'}" transform="rotate(${i%2?20:-20} ${75+i%6*22} ${101+Math.floor(i/6)*20})"/>`).join('')}<path d="M88 49v-15m42 15v-23m42 23V34" stroke="#87a691" stroke-width="3" stroke-linecap="round" class="station-activity"/></svg>`;}
renderBsfFlow=function(){renderControlPanel29();};
openBsfPanel=function(code){cpCode=code;navigateScreen('control');cpCode=code;renderApp();};
function renderControlPanel29(){const o=op29(),lot=dateLot29(),sources=sourceSerials29(),last=state.operationRuns.find(x=>x.operation===o.code);document.getElementById('view-workcenters').innerHTML=`<div class="cp-heading"><div><div class="section-kicker">PRODUCCIÓN</div><h1>Control Panel</h1></div><div class="cp-select"><label>Workcenter<select class="select" aria-label="Workcenter" onchange="cpCode=this.value;renderApp()">${state.cpOperations.map(x=>`<option value="${x.code}" ${x.code===o.code?'selected':''}>${esc(x.wc+' · '+x.workcenter)}</option>`).join('')}</select></label><span class="status-live"><i></i>Disponible</span></div></div><div class="cp-route">${state.cpOperations.slice(0,13).map(x=>`<button class="${x.code===o.code?'active':''}" onclick="cpCode='${x.code}';renderApp()">${esc(x.name)}</button>`).join('')}</div><div class="process-board" id="processBoard"><section class="port input-port"><div class="port-label">INPUT</div><div class="port-symbol">${icon29(o.code==='EGG'?'fly':'box')}</div><h2>${esc(o.inputName)}</h2>${o.code==='EGG'?'<label>Referencia de jaula<input class="input" id="cpCage" placeholder="Ej. Jaula 01"></label>':`<label>Serial de entrada<select class="select" id="cpInput" onchange="updateCPSource29()"><option value="">Seleccionar contenedor</option>${sources.map(x=>`<option value="${esc(x.serial)}">${esc(x.serial+' · '+x.qtyCurrent+' '+x.unit)}</option>`).join('')}</select></label><label>Cantidad a procesar<input class="input" type="number" step="any" min="0.001" id="cpConsume"></label>`}<div class="port-caption" id="sourceLot">${o.code==='EGG'?'Jaula de reproducción':'Saldo y lote del contenedor'}</div></section><div class="process-arrow">${icon29('arrow')}<span class="moving-container">${icon29('box')}</span></div><section class="station"><div class="station-tag">${esc(o.wc)}</div><h2>${esc(o.name)}</h2>${scene29(o)}<div class="duration"><span>Tiempo de proceso</span><strong>${esc(o.duration==='Por definir'?'—':o.duration)}</strong></div><div class="operator-row">${esc(shellSession?.user||'Alejandro')} <span>● En estación</span></div></section><div class="process-arrow outgoing">${icon29('arrow')}<span class="moving-container">${icon29('box')}</span></div><section class="port output-port"><div class="port-label">OUTPUT</div><div class="port-symbol">${icon29('box')}</div><h2>${esc(o.output)}</h2><label>Cantidad de salida<div class="quantity-unit"><input class="input" id="cpOutputQty" type="number" min="0.001" step="any" placeholder="0.00" aria-label="Cantidad de salida"><strong>${esc(o.unit)}</strong></div></label><label>Lote de producción<input class="input lot-display" id="cpLot" readonly value="${o.code==='EGG'?lot.label:''}" placeholder="Se hereda del contenedor"></label><div class="output-serial" id="cpOutputSerial">${last?'Último serial: '+esc(last.serial):'Serial asignado al registrar'}</div></section></div><div class="cp-actions"><button class="btn primary" onclick="reportProduction29()" id="reportProduction">${icon29('box')}Registrar producción</button><button class="btn soft" onclick="openCPLog29()">Historial de producción</button><span id="cpRecordMessage" aria-live="polite"></span></div>`;}
function updateCPSource29(){const c=state.serials.find(x=>x.serial===document.getElementById('cpInput').value);document.getElementById('cpConsume').value=c?.qtyCurrent||'';document.getElementById('cpLot').value=c?.lot||'';document.getElementById('sourceLot').textContent=c?c.qtyCurrent+' '+c.unit+' · '+(c.lot||'Sin lote'):'Saldo y lote del contenedor';}
function validateOutput29(o,qty){if(!Number.isFinite(qty)||qty<=0)throw Error('Captura una cantidad de salida mayor que cero.');if(!o.units.includes(o.unit))throw Error('La unidad no está autorizada para la operación.');}
function recordCP29(s,o,{qty,inputSerial,consume,cage,date=new Date()}){validateOutput29(o,qty);let source,lotId,label;if(o.code==='EGG'){const lot=dateLot29(date);lotId=lot.id;label=lot.label;}else{source=s.serials.find(x=>x.serial===inputSerial&&x.active&&x.part===o.input&&!x.receiptPending30&&x.status==='OK');if(!source)throw Error('Selecciona un serial de entrada válido.');if(!Number.isFinite(consume)||consume<=0||consume>source.qtyCurrent)throw Error('La cantidad de entrada excede el saldo disponible.');lotId=source.productionLot||source.lot;label=source.lot;if(!lotId)throw Error('El contenedor de entrada no tiene lote de producción.');}
 const prefix=s.setupTables.Serial_Prefix.find(x=>x.code==='BSF'),serial='BSF'+String(++prefix.lastNumber).padStart(6,'0');if(!s.productionLots.some(l=>l.id===lotId))s.productionLots.push({id:lotId,label,date:lotId});if(source){source.qtyCurrent=round(source.qtyCurrent-consume);if(source.qtyCurrent===0){source.active=false;source.status='CONSUMED';}s.genealogy.unshift({ts:nowDateTimeLocal(),parent:source.serial,child:serial,action:'PRODUCTION',qty:consume,ref:o.name});}const c={active:true,serial,part:o.part,desc:o.output,qtyCurrent:qty,unit:o.unit,containerType:'BSF',status:'OK',origin:'PRODUCTION',location:o.wc,lot:label,productionLot:lotId,notes:cage||''};s.serials.push(c);s.operationRuns.unshift({serial,operation:o.code,qty,unit:o.unit,lot:label,productionLot:lotId,inputSerial:source?.serial||'',inputQty:consume||0,at:date.toISOString(),wc:o.wc});return c;}
async function reportProduction29(){if(!requireLevel(2,'control'))return;const o=op29(),qty=Number(document.getElementById('cpOutputQty').value),inputSerial=document.getElementById('cpInput')?.value,consume=Number(document.getElementById('cpConsume')?.value),cage=document.getElementById('cpCage')?.value;try{const next=structuredClone(state),c=recordCP29(next,o,{qty,inputSerial,consume,cage});document.getElementById('processBoard').classList.add('running');document.getElementById('reportProduction').disabled=true;await new Promise(r=>setTimeout(r,1400));state=next;saveState();renderApp();document.getElementById('cpRecordMessage').textContent=c.serial+' · '+c.qtyCurrent+' '+c.unit+' · '+c.lot;showMsg('Producción registrada');}catch(e){showMsg(e.message,true);}}
function openCPLog29(){configDialog('Historial de producción',table(['Fecha','Proceso','Serial','Cantidad','Lote'],state.operationRuns.map(x=>`<tr><td>${esc(new Date(x.at).toLocaleString('es-MX'))}</td><td>${esc(x.operation)}</td><td>${esc(x.serial)}</td><td>${esc(x.qty+' '+x.unit)}</td><td>${esc(x.lot)}</td></tr>`)));}
